from pathlib import Path
import json,struct,sys

def unpack(data,offset=0):
 tag=data[offset];offset+=1
 if tag<0x80:return tag,offset
 if tag>=0xe0:return tag-256,offset
 if 0xa0<=tag<=0xbf:
  n=tag&31;return data[offset:offset+n].decode(),offset+n
 if 0x80<=tag<=0x9f:
  n=tag&15;kind='map' if tag<0x90 else 'array'
 elif tag in (0xc0,0xc2,0xc3):return {0xc0:None,0xc2:False,0xc3:True}[tag],offset
 elif tag in (0xca,0xcb,0xcc,0xcd,0xce,0xcf,0xd0,0xd1,0xd2,0xd3):
  fmt={0xca:'f',0xcb:'d',0xcc:'B',0xcd:'H',0xce:'I',0xcf:'Q',0xd0:'b',0xd1:'h',0xd2:'i',0xd3:'q'}[tag]
  return struct.unpack_from('>'+fmt,data,offset)[0],offset+struct.calcsize(fmt)
 elif tag in (0xc4,0xc5,0xc6,0xd9,0xda,0xdb,0xdc,0xdd,0xde,0xdf):
  size={0xc4:1,0xc5:2,0xc6:4,0xd9:1,0xda:2,0xdb:4,0xdc:2,0xdd:4,0xde:2,0xdf:4}[tag]
  n=int.from_bytes(data[offset:offset+size],'big');offset+=size
  if tag in (0xc4,0xc5,0xc6,0xd9,0xda,0xdb):
   v=data[offset:offset+n];return (v.hex() if tag<=0xc6 else v.decode()),offset+n
  kind='array' if tag in (0xdc,0xdd) else 'map'
 else:raise ValueError('Unsupported MessagePack tag '+hex(tag))
 if kind=='array':
  result=[]
  for _ in range(n):v,offset=unpack(data,offset);result.append(v)
 else:
  result={}
  for _ in range(n):k,offset=unpack(data,offset);v,offset=unpack(data,offset);result[k]=v
 return result,offset

def metadata(binary):
 found=[];offset=0
 while True:
  begin=binary.find(b'\x7fELF\x02\x01',offset)
  if begin<0:break
  offset=begin+4
  elf=struct.unpack_from('<16sHHIQQQIHHHHHH',binary,begin)
  if elf[2]!=224:continue
  shoff,shsize,count=elf[6],elf[11],elf[12]
  if shsize!=64:continue
  for i in range(count):
   header=struct.unpack_from('<IIQQQQIIQQ',binary,begin+shoff+i*shsize)
   if header[1]!=7:continue
   pos=begin+header[4];end=pos+header[5]
   while pos<end:
    namesz,descsz,kind=struct.unpack_from('<III',binary,pos);pos+=12
    name=binary[pos:pos+namesz].rstrip(b'\0');pos+=(namesz+3)&~3
    description=binary[pos:pos+descsz];pos+=(descsz+3)&~3
    if name==b'AMDGPU' and kind==32:
     value,consumed=unpack(description);assert consumed==len(description)
     found.append(dict(elf_offset=begin,metadata=value))
 return found
if __name__=='__main__':
 path=Path(sys.argv[1]);result=metadata(path.read_bytes())
 assert result,'No AMDGPU metadata found'
 if '--full' in sys.argv:print(json.dumps(result,indent=2))
 else:
  for record in result:
   for kernel in record['metadata'].get('amdhsa.kernels',[]):
    print(json.dumps({k:v for k,v in kernel.items() if k in ('.name','.sgpr_count','.vgpr_count','.group_segment_fixed_size','.private_segment_fixed_size','.wavefront_size','.max_flat_workgroup_size')},sort_keys=True))

