#include <algorithm>
#include <cstdint>
#include <cstdio>
#include <fstream>
#include <iostream>
#include <stdexcept>
#include <string>
#include <vector>
int main(int argc,char** argv)try{
    if(argc!=2)throw std::runtime_error("manifest");
    std::ifstream manifest(argv[1]);std::string path;size_t index=0;
    while(std::getline(manifest,path)){
        std::ifstream f(path,std::ios::binary|std::ios::ate);
        if(!f || f.tellg()!=2097152)throw std::runtime_error("state extent");
        std::vector<uint32_t> words(524288);f.seekg(0);f.read(reinterpret_cast<char*>(words.data()),2097152);
        if(!f)throw std::runtime_error("state read");
        uint64_t zero=0,negative_zero=0,subnormal=0,nonfinite=0;
        unsigned minimum=255,maximum=0,minimum_at=0;
        for(unsigned i=0;i<words.size();++i){
            const uint32_t magnitude=words[i]&0x7fffffffu,exponent=magnitude>>23u;
            if(!magnitude){++zero;negative_zero+=words[i]>>31u;continue;}
            if(exponent==255u){++nonfinite;continue;}
            if(!exponent)++subnormal;
            if(exponent<minimum){minimum=exponent;minimum_at=i;}
            maximum=std::max(maximum,exponent);
        }
        std::cout<<"{\"index\":"<<index++<<",\"elements\":"<<words.size()<<",\"zero\":"<<zero
            <<",\"negative_zero\":"<<negative_zero<<",\"subnormal\":"<<subnormal<<",\"nonfinite\":"<<nonfinite
            <<",\"nonzero_minimum_biased_exponent\":"<<(zero+nonfinite==words.size()?-1:int(minimum))
            <<",\"nonzero_maximum_biased_exponent\":"<<(zero+nonfinite==words.size()?-1:int(maximum))
            <<",\"minimum_exponent_first_index\":"<<minimum_at<<"}\n";
    }
    if(!manifest.eof() || index!=180u)throw std::runtime_error("manifest count");
}catch(const std::exception& e){std::cerr<<e.what()<<'\n';return 2;}

